# POST /api/sheets/{sheetId}/people/{personId}/retire — retire a person from a date (blank: the sheet's today). A date
# that is not yyyy-MM-dd is a 400 and a person not on the sheet a 404, neither writing anything. The person counts as
# retired at once, whatever the date; no claim of theirs may then be dated after it. From the day the retirement date is
# reached (the sheet's today on or after it), their OPEN and PENDING claims not bound by a statement leave every live
# total, and the figures that moves are written. Responds with the person as stored.
validate:
  class: net.officefloor.hq.app.person.ValidateRetire
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: retire
retire:
  class: net.officefloor.hq.app.person.RetirePerson
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.person.RecordPersonRetired
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
# POST /api/sheets/{sheetId}/bulk-open — open the selected claims together. Each selected claim that can be opened
# (a DRAFT whose due-by is not inside a closed period) is opened as the single open does, in list order: people by their
# place in the list, a person's claims newest first, so each takes the sheet's next number in that order and writes
# its own CLAIM_OPENED, ROLLUP and TOTALS lines. Each that cannot (or is not on the sheet) is left as it is and
# counted refused. Responds with how many were opened and how many refused.
validate:
  class: net.officefloor.hq.app.claim.ValidateBulkOpen
  next: open
open:
  class: net.officefloor.hq.app.claim.OpenClaims
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithBulkOpen
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Retires the person from the date; a retirement given no date is from the sheet's today. */
public class RetirePerson {
    public void retire(@Val Person person, @Val Retirement retirement, SheetRepository sheets, PersonRepository people,
            Out<Person> retired) {
        LocalDate from = retirement.from() != null ? retirement.from() : sheets.today(person.sheetId());
        people.retire(person.sheetId(), person.id(), from);
        retired.set(new Person(person.id(), person.sheetId(), person.name(), person.grade(), person.version(), from.toString(),
                person.grades(), person.holds(), person.terms(), person.contact(), person.aliases()));
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;

/** A retirement once validated: the date (null when none was given, so the sheet's today) and who gives it. */
public record Retirement(LocalDate from, String by) {
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupBefore;
import net.officefloor.plugin.variable.Val;

/** Writes PERSON_RETIRED to the audit file once the retirement is stored. Then writes the figures the change moved
 *  (see Rollup): once their retirement date is reached, a retired person's OPEN and PENDING claims not bound by a
 *  statement leave every live total. */
public class RecordPersonRetired {
    public void record(@Val Person person, @Val Retirement retirement, @Val RollupBefore before, Rollup rollup,
            Audit audit) {
        audit.record("PERSON_RETIRED sheet=" + person.sheetId() + " by=" + retirement.by() + " name=" + person.name()
                + " from=" + person.retiredFrom());
        rollup.record(person.sheetId(), retirement.by(), before);
    }
}
package net.officefloor.hq.app.person;

/** Body of retiring a person: the date they are retired from (blank: the sheet's today), and who retires them. */
public record RetireRequest(String from, String by) {
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: the date is blank or yyyy-MM-dd. */
public class ValidateRetire {
    public void validate(@RequestBody RetireRequest request, Out<Retirement> retirement) throws InvalidPersonException {
        String from = request == null || request.from() == null ? "" : request.from().trim();
        LocalDate parsed = null;
        if (!from.isEmpty()) {
            try {
                parsed = LocalDate.parse(from);
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("The retirement date must be yyyy-MM-dd");
            }
        }
        retirement.set(new Retirement(parsed, request == null || request.by() == null ? "" : request.by().trim()));
    }
}

