  const [selected, setSelected] = useSelectedPeople();
  return (
    <td>
      <input
        type="checkbox"
        data-testid="person-select"
        checked={selected.includes(person.id)}
        onChange={(e) =>
          setSelected(e.target.checked ? [...selected, person.id] : selected.filter((id) => id !== person.id))
        }
      />
    </td>
  );
